Hypothesis LAY : L5A.as0_layout L C.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps (hl_segs L) (@mkst fx R (Z_to_bv 64 pc) M (seg_rom (hl_segs L))) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom (hl_segs L))) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Variable CL : Z.
Abbreviation IC := PMLA.C_xasan.
Abbreviation EC := PMESA.EC_xasan.
Abbreviation RSEGS := (hl_segs L).
Hypothesis ACC_CLOSE : PMESA.img_aacc HI EVEA.CLOSE_TXT 1.                                                  (* [comment removed for export] *)
Hypothesis FOOTXC : forall a, PMLA.in_footx PMLA.C_xasan a -> ~ hl_rt_static L a /\ ~ hl_rt_ro L a.         (* [comment removed for export] *)
Hypothesis NEWLINE2_OK : PMESA.new_line2_specA L ar HI IC CL EVEA.PC_NL.                                   (* [comment removed for export] *)
